#!/usr/bin/env node
// Rebuilds js/offline-bundle.js so the site also works when opened straight from a folder (file://).
// Browsers block fetch() on file:// pages, which is how pages load the shared header, footer and templates.
// The bundle holds a copy of every page + data/imageslots.json and is loaded ONLY on file:// pages
// (web servers never load it). Run after editing any .dc.html file:  node scripts/build-offline-bundle.mjs
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const files = {};
for (const n of readdirSync(root).filter((n) => n.endsWith('.dc.html') && n !== 'LiveWalkthrough.dc.html').sort()) files[n] = readFileSync(join(root, n), 'utf8');
files['data/imageslots.json'] = readFileSync(join(root, 'data/imageslots.json'), 'utf8');
function BODY(json) {
  return '/* Generated by scripts/build-offline-bundle.mjs. Do not edit. Loaded only when the site is opened from a folder (file://). */\n' +
    '(function () {\n  var F = ' + json + ';\n' + RUNTIME;
}

const RUNTIME = "  var base = location.href.replace(/[?#].*$/, '').replace(/[^/]*$/, '');\n  var real = window.fetch ? window.fetch.bind(window) : null;\n  window.fetch = function (input, init) {\n    var url = typeof input === 'string' ? input : (input && input.url) || '';\n    var abs; try { abs = new URL(url, location.href).href; } catch (e) { abs = url; }\n    var rel = abs.indexOf(base) === 0 ? decodeURIComponent(abs.slice(base.length).replace(/[?#].*$/, '')) : null;\n    if (rel !== null && Object.prototype.hasOwnProperty.call(F, rel))\n      return Promise.resolve(new Response(F[rel], { status: 200, headers: { 'content-type': /\\.json$/.test(rel) ? 'application/json' : 'text/html; charset=utf-8' } }));\n    return real ? real(input, init) : Promise.reject(new TypeError('fetch is not available'));\n  };\n})();\n";

writeFileSync(join(root, 'js/offline-bundle.js'), BODY(JSON.stringify(files)));
console.log('js/offline-bundle.js rebuilt with ' + Object.keys(files).length + ' files.');
